/**
 * Dual-audience supplement education library (230 original paraphrased sheets).
 * Data generated by scripts/generate-education-library.mjs — OCR prose is not stored.
 */

import libraryData from "@/data/education-library.json";
import { getNutritionBlogMeta } from "@/lib/blog-posts-nutrition";

export type LibraryRelatedBlog = {
  slug: string;
  title: string;
  summary: string;
};

export type LibrarySection = {
  heading: string;
  body: string;
};

export type LibraryFaq = {
  question: string;
  answer: string;
};

export type LibraryCategoryId =
  | "start-here"
  | "minerals"
  | "vitamins"
  | "amino-acids-protein"
  | "fatty-acids"
  | "herbal"
  | "wellness-themes"
  | "sports-weight"
  | "reference-forms";

export type LibraryArticle = {
  slug: string;
  sourcePage: number;
  section: string;
  category: LibraryCategoryId | string;
  topicKey: string;
  topicTitle: string;
  variantLabel: string;
  needsReview: boolean;
  title: string;
  summary: string;
  status: "published" | "coming-soon";
  topics: string[];
  mskRelevant: boolean;
  sections: LibrarySection[];
  caveats: string[];
  faqs: LibraryFaq[];
};

export type LibraryTopic = {
  topicKey: string;
  title: string;
  category: LibraryCategoryId | string;
  summary: string;
  mskRelevant: boolean;
  sheetCount: number;
  needsReview: boolean;
  articles: LibraryArticle[];
  relatedBlog?: LibraryRelatedBlog;
};

